INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tu_d12397170180f683', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_urdu_grammar', 'معنوں کے لحاظ سے فعل کے کتنے قسمیں ہیں؟', '{"A":"دو","B":"چار","C":"پانچ","D":"ان میں سے کوئی نہیں"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation فعل کی اقسام معنی کے لحاظ سے فعل کی چار قسمیں ہیں: (١) فعل لازم (٢) فعل متعدی (٣) فعل ناقص (٤) فعل معدولہ فعل لازم وہ فعل ہے جس میں کام کا اثر صرف فاعل تک محدود رہے اور اسے مفعول کی ضرورت نہ ہو مثالیں عمران جاگا طارق سویا بچہ رویا فعل متعدی وہ فعل ہے جس کو مکمل ہونے کے لیے فاعل کے علاوہ مفعول کی بھی ضرورت ہو مثالیں حامد نے خط لکھا عمران نے کھانا کھایا فعل ناقص وہ فعل ہے جس سے کسی چیز کا ہونا یا نہ ہونا ظاہر ہو فعل معدولہ وہ فعل ہے جو کسی کام کو متبادل کے ساتھ کرنے کا اظہار کرےLast verified on 02-10-2026', 0, 0, 0, 1790968558957) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tu_f8a9d55ba00a38e4', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_urdu_grammar', 'وہ اسم جو کسی جاندار یا بے جان کی آواز کو ظاہر کرے، کیا کہلاتا ہے؟', '{"A":"اسم معرفہ","B":"اسم نکرہ","C":"اسم مصدر","D":"اسم صوت"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation اسم صوت وہ اسم ہوتا ہے جو کسی جاندار یا بے جان کی آواز کو ظاہر کرے، جیسے "آہٹ"، "ڈھول"، "ہنکارہ" وغیرہ۔اسم معرفہ وہ اسم ہے جس کا مخصوص اور معروف مطلب ہوتا ہے، جیسے کسی شخص یا جگہ کا نام۔اسم نکرہ وہ اسم ہوتا ہے جو عام طور پر کسی شخص، چیز، یا جگہ کو ظاہر کرتا ہے اور اس کا کوئی خاص نام نہیں ہوتا۔Last verified on 02-10-2026', 0, 0, 0, 1790968558957) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tu_5c3f3c3d3e39cb50', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_urdu_grammar', 'وہ اسم جو نہ کسی سے بنا ہو اور نہ ہی اس سے کوئی کلمہ بنایا جا سکے اسے کیا کہتے ہیں؟', '{"A":"اسم مصدر","B":"اسم مشتق","C":"اسم جامد","D":"اسم معرفہ"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation اسم جامد وہ اسم ہوتا ہے جو نہ کسی سے بنا ہو اور نہ ہی اس سے کوئی دوسرا کلمہ بنایا جا سکے۔یہ ایک بنیادی اور غیر تبدیل شدہ اسم ہوتا ہے، جیسے "کتاب" یا "مکہ"۔Last verified on 02-10-2026', 0, 0, 0, 1790968558957) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tu_9a3892979d5ed792', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_urdu_grammar', 'بناوٹ کے لحاظ سے اسم کی کتنی اقسام ہیں؟', '{"A":"دو","B":"تین","C":"چار","D":"پانچ"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation بناوٹ کے لحاظ سے اسم کی تین اقسام ہیںاسمِ جامد: جو کسی دوسرے لفظ سے نہ بنا ہو۔مثال: قلم، کتاب، گھراسمِ مصدر: جس سے کسی کام کا ہونا یا کرنا ظاہر ہو۔مثال: پڑھنا، لکھنا، کھانااسمِ مشتق: جو کسی دوسرے لفظ سے بنایا گیا ہو۔مثال: پڑھنے والا، لکھاری، کاریگر', 0, 0, 0, 1790968558957) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tu_e948d1d760724fcf', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_urdu_grammar', 'مرکب جملہ کسے کہتے ہیں؟', '{"A":"ایسا جملہ جو دو یا زیادہ جملوں کو کسی حرف کی مدد سے ملا کر بنایا جائے","B":"ایسا جملہ جو مکمل نہ ہو","C":"ایسا جملہ جس میں صرف ایک فقرہ ہو","D":"ان میں سے کوئی نہیں"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation مرکب جملہ وہ ہوتا ہے جس میں دو یا دو سے زیادہ جملے حرفِ ربط کے ذریعے آپس میں جُڑے ہوتے ہیں۔مثلاً: میں اسکول گیا اور دوستوں سے ملا۔Last verified on 02-10-2026', 0, 0, 0, 1790968558957) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tu_bbf620e1ec1438e3', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_urdu_grammar', 'احمد ندیم قاسمی کا کونسا افسانہ ہے؟', '{"A":"زیور کا ڈبہ","B":"بھروپیا","C":"الحمداللہ","D":"ان میں سے کوئی نہیں"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation الحمدللہ احمد ندیم قاسمی کا ایک مشہور اور شاہکار افسانہ ہے۔اس میں ایک غریب مولوی مولوی ابوالبرکات کی زندگی اور سفید پوشی کی عکاسی کی گئی ہے۔افسانے میں معاشرتی مسائل کو مؤثر انداز میں پیش کیا گیا ہے۔Last verified on 15-08-2026', 0, 0, 0, 1790968558957) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tu_cb1d2a46374c32bf', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_urdu_grammar', 'وہ فعل جس کا فاعل معلوم ہو۔ وہ کیا کہلاتا ہے؟', '{"A":"فعل مجهول","B":"فعل  معروف","C":"فعل متعدی","D":"ان میں سے کوئی نہیں"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation ایسا فعل جس کا فاعل معلوم ہو اسے فعل معروف کہا جاتا ہے۔ معروف کے معنی مشہور یا جانا پہچانا کے ہیں روز مرہ زندگی میں بات کرنے کے معمول کے انداز کو فعل معروف کہتے ہیں۔ شاہدہ نمازپڑھتی ہے، عمران نےآم کھایا، عمران کتاب لائے گا۔ اِن جملوں میں پڑھتی ہے، کھایا اورلائے گا فعل معروف ہیں۔Last verified on 09-08-2026', 0, 0, 0, 1790968558957) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tu_b3e232973a0d7c22', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_urdu_grammar', 'غزل کا آخری شعر جس میں شاعر اپنا تخلص بیان کرتا ہے، اسے کیا کہتے ہیں؟', '{"A":"مطلع","B":"مقطع","C":"دونوں","D":"ان میں سے کوئی بھی نہیں"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation غزل کے آخری شعر کو مقطع کہتے ہیں۔عموماً اس میں شاعر اپنا تخلص استعمال کرتا ہے۔Last verified on 08-08-2026', 0, 0, 0, 1790968558957) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tu_3e17393c7f0b4262', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_urdu_grammar', 'اگرچہ کون سا حرف ہے؟', '{"A":"حرفِ عطف","B":"حرفِ ربط","C":"حرفِ نفی","D":"حرفِ شرط"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation اگرچہ ایک حرفِ شرط ہے، جو شرط یا رعایت کا مفہوم دیتا ہے۔اگر شرط کا مفہوم دیتا ہے، جبکہ "چہ" کے معنی "بھی" یا "ایسا ہو" کے ہیں۔Last verified on 28-07-2026', 0, 0, 0, 1790968558997) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tu_fee86acc1f7c38ab', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_urdu_grammar', 'استفہامیہ جملے کونسے جملے ہوتے ہیں؟', '{"A":"سوالیہ","B":"ندائیہ","C":"منفی","D":"ان میں سے کوئی نہیں"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation استفہامیہ جملے وہ جملے ہوتے ہیں جو سوال کرنے کے لیے استعمال کیے جاتے ہیں۔ان جملوں میں سوالیہ نشان (?) لگتا ہے، جیسے "کیا تم نے کھانا کھایا؟"۔Last verified on 20-06-2026', 0, 0, 0, 1790968558997) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tu_7d0d26c9cc3bcd97', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_urdu_grammar', 'جدید شاعری کا امام کس کا خطاب ہے؟', '{"A":"بشری رحمن","B":"مولانا حسرت موہانی","C":"خواجہ میر درد","D":"مولانا الطاف حسین حالی"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation مولانا الطاف حسین حالی کو جدید اردو شاعری کا امام کہا جاتا ہے۔انہوں نے اردو شاعری میں اصلاحی اور حقیقت پسندانہ رجحان کو فروغ دیا۔ان کی شاعری میں سماجی اصلاح، سادگی اور مقصدیت نمایاں ہے۔Last verified on 02-06-2026', 0, 0, 0, 1790968558997) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tu_f4436021ff7b6eab', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_urdu_grammar', 'مرکب اشاری کس سے مل کر بنتا ہے؟', '{"A":"اسم اشارہ اور تلمیح","B":"اسم اشارہ اور مشارالیہ","C":"اسم اشارہ اور تشبیہ","D":"ان میں سے کوئی نہیں"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation مرکب اشاری دو اجزاء سے مل کر بنتا ہے: اسم اشارہ (جیسے: یہ، وہ) اور مشارالیہ (جس چیز کی طرف اشارہ کیا جائے)۔مثال: یہ کتاب، وہ لڑکا — یہاں "یہ" اور "وہ" اسم اشارہ ہیں، جبکہ "کتاب" اور "لڑکا" مشارالیہ ہیں۔Last verified on 19-04-2026', 0, 0, 0, 1790968558997) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tu_350dcff070b2a086', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_urdu_grammar', 'اسم معرفہ کی کتنی قسمیں ہیں؟', '{"A":"چار","B":"پانچ","C":"چھ","D":"ان میں سے کوئی نہیں"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation اسم معرفہ: یہ وہ اسم ہوتا ہے جو کسی مخصوص شخص، جگہ یا چیز کو ظاہر کرتا ہے۔اس کی اقسام ہیں:اسم علم: جو کسی خاص شخص یا جگہ کے نام کے طور پر استعمال ہوتا ہے (مثلاً: پاکستان، احمد)۔اسم ضمیر: جو کسی شخص یا چیز کی جگہ ضمیر کے طور پر استعمال ہوتا ہے (مثلاً: وہ، یہ)۔اسم اشارہ: جو کسی مخصوص چیز یا شخص کی طرف اشارہ کرتا ہے (مثلاً: یہ، وہ)۔اسم موصول: جو کسی جملے کے ساتھ مل کر مکمل معنی فراہم کرتا ہے (مثلاً: جو، جس)۔Last verified on 19-04-2026', 0, 0, 0, 1790968558997) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tu_932d4633ff9c8c06', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_urdu_grammar', 'سکتہ کی علامت کونسی ہے؟', '{"A":"!","B":"؟","C":"،","D":"ان میں سے کوئی نہیں"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation سکتہ کی علامت ، ہے۔', 0, 0, 0, 1790968558997) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tu_0ce0fb0074477ba2', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_urdu_grammar', 'گرامر کی رو سے لفظ ''قینچی'' کونسا اسم ہے؟', '{"A":"اسم صفت","B":"اسم فاعل","C":"اسم آلہ","D":"ان میں سے کوئی نہیں"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation قینچی ایک ایسا اسم ہے جو کسی آلہ یا چیز کو ظاہر کرتا ہے جس سے کوئی کام لیا جاتا ہے۔اسم آلہ ان اسماء کو کہتے ہیں جو کسی کام کو انجام دینے والے آلے یا اوزار کو ظاہر کریں، جیسے: قینچی، چھری، ہتھوڑا۔', 0, 0, 0, 1790968558997) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tu_f42bddeee16319e9', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_urdu_grammar', 'اسم معرفہ کی اقسام کونسی ہے؟', '{"A":"اسم علم، اسم ضمیر، اسم مصدر، اسم موصول","B":"اسم علم، اسم ضمیر، اسم اشارہ، اسم موصول","C":"اسم علم، اسم صفت، اسم اشارہ، اسم موصول","D":"ان میں سے کوئی نہیں"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation اسم معرفہ: یہ وہ اسم ہوتا ہے جو کسی مخصوص شخص، جگہ یا چیز کو ظاہر کرتا ہے۔اس کی چار اقسام ہیں:اسم علم: جو کسی خاص شخص یا جگہ کے نام کے طور پر استعمال ہوتا ہے (مثلاً: پاکستان، احمد)۔اسم ضمیر: جو کسی شخص یا چیز کی جگہ ضمیر کے طور پر استعمال ہوتا ہے (مثلاً: وہ، یہ)۔اسم اشارہ: جو کسی مخصوص چیز یا شخص کی طرف اشارہ کرتا ہے (مثلاً: یہ، وہ)۔اسم موصول: جو کسی جملے کے ساتھ مل کر مکمل معنی فراہم کرتا ہے (مثلاً: جو، جس)۔', 0, 0, 0, 1790968558997) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tu_a8fc3fca367eada8', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_urdu_grammar', 'اس ڈائری یا نوٹ بک کو جس میں شاعر اپنا تخلص یا منتخب اشعار بیان کرتا ہے کہتے ہیں', '{"A":"دیوان","B":"بیاض","C":"کلیات","D":"None"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation بیاض کا مطلب ایک ایسی کاپی یا کتاب ہے جس میں کوئی شخص پسندیدہ اشعار، مضامین یا تحریریں درج کرتا ہے. قدیم زمانے میں شعراء، ادیب اور ذوق رکھنے والے لوگ اپنی بیاضیں ساتھ رکھتے تھے جس میں وہ اپنا کلام یا پسندیدہ تحریریں لکھتے اور مشاعروں یا محفلوں میں لے جاتے تھے. بیاض کے لغوی معنی "سفید، سفید کور والی کتاب" کے ہیں', 0, 0, 0, 1790968559038) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tu_f295174f4fc4a7eb', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_urdu_grammar', 'وہ نبیوں میں رحمت لقب پانے والا کس کا مصرع ہے؟', '{"A":"حفیظ تائب","B":"مسدسِ حالی","C":"مولانا ظفر علی خان","D":"چشتی"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation مسدس حالی کی ایک مشہور نعتکفار و مشرکین کیا، حیوانات کے لئے بھی وہؐ سراپا رحمت تھے۔خود پر کوڑا کرکٹ پھینکنے والی کے وہ تیمار دار تھے۔ طائف میں پتھر مار کر لہو لہان کر دینے والوں کے لئے وہؐ سراپا خیر تھے۔', 0, 0, 0, 1790968559038) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tu_bf86fd926281e60a', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_urdu_grammar', 'جملہ اسمیہ کے کتنے بنیادی اجزاء ہوتے ہیں؟', '{"A":"تین","B":"چار","C":"پانچ","D":"ان میں سے کوئی نہیں"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation جملہ اسمیہ کے بنیادی اجزاء ہوتے ہیں: مبتدا، خبر، اور بدل (اگر ہو)۔عام طور پر تین بنیادی اجزاء شمار کیے جاتے ہیں۔', 0, 0, 0, 1790968559038) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tu_1671946c1009d474', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_urdu_grammar', 'وہ کونسا فعل ہے۔ جب تک فاعل کے علاوہ کوئی اور اسم یا صفت اس کے ساتھ نہ ملے، وہ بات کو مکمل نہیں کرتا؟', '{"A":"فعل تام","B":"فعل ناقص","C":"فعل اضطراری","D":"فعل لازم"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation فعل ناقص وہ فعل ہوتا ہے جو فاعل کے علاوہ کسی اسم یا صفت کے بغیر اپنی بات مکمل نہیں کرتا۔مثال کے طور پر: "وہ بہت خوش ہے" یہاں "ہے" ایک ناقص فعل ہے کیونکہ اس کے ساتھ "خوش" (صفت) کی ضرورت ہے۔', 0, 0, 0, 1790968559038) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tu_56277ed256a8f3d3', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_urdu_grammar', 'ان میں سے کونسا لفظ مذکر اور مؤنث دونوں ہیں؟', '{"A":"وارث","B":"زمین","C":"ماں","D":"آب"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation وارث ایک اسم مشترک ہے — یعنی ایسا لفظ جو مذکر اور مونث دونوں کے لیے استعمال ہوتا ہے۔مثالیں: - وہ وارث ہے۔ (مرد کے لیے) - وہ بھی جائیداد کی وارث ہے۔ (عورت کے لیے)', 0, 0, 0, 1790968559038) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tu_7ef07e56712ed981', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_urdu_grammar', 'ایسا اسم جس میں کسی کام کا ہونا یا کرنا زمانے کے تعلق کے بغیر پایا جائے ـــــــ کہلاتا ہے؟', '{"A":"اسمِ جامد","B":"اسم مصدر","C":"اسم مشتق","D":"ان میں سے کوئی نہیں"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation ایسا اسم جس میں کسی کام کا ہونا یا کرنا زمانے کے تعلق کے بغیر پایا جائے، اسے اسم مصدر کہا جاتا ہے۔مثالیں: لکھنا، پڑھنا، سونا، دوڑنا، کھانا وغیرہ۔ (ان الفاظ میں کام کا نام تو ہے، مگر یہ پتہ نہیں چلتا کہ کام کس زمانے میں ہوا ہے)۔ Last updated by NS on 06 May 2026', 0, 0, 0, 1790968559038) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tu_3d56fd8b729ceccb', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_urdu_grammar', 'قواعد کی رو سے بے معنی الفاظ کو کیا کہتے ہیں؟', '{"A":"کلمہ","B":"حروف جار","C":"مہمل","D":"فعل معروف"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation مہمل وہ الفاظ یا جملے ہوتے ہیں جو کسی خاص معنی یا مقصد کے بغیر استعمال ہوتے ہیں۔یہ الفاظ زبان کے قواعد کے مطابق بے معنی اور غیر مفہوم ہوتے ہیں۔', 0, 0, 0, 1790968559038) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tu_4d0aa6b26ec3d64e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_urdu_grammar', 'وہ مرکب جس سے سننے والا پورا مطلب سمجھ سکے، وہ کیا کہلاتا ہے؟', '{"A":"مرکب تام","B":"مرکب ناقص","C":"مرکب عطفی","D":"مرکب توصیفی"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation مرکب کی تعریفکلمات کے مجموعہ کو مرکب کہتے ہیں۔مرکب کی اقساممرکب کی دو قسمیں ہوتی ہیں(1) مرکب ناقص (2) مرکب تام(1) مرکب ناقص وہ مرکب ہے جس سے سننے والے کو پورا مطلب سمجھ میں نہ آئے۔(2) مرکب تام وہ مرکب ہے جس کے سننے سے پورا مطلب سمجھ میں آجائے۔', 0, 0, 0, 1790968559038) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tu_2421bda5dcbdb4b6', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_urdu_grammar', 'اس کے چہرے پر ہر وقت مسکراہٹ رہتی ہے۔ اس جملے میں ''مسکراہٹ'' کا تعلق کونسے اسم سے ہے؟', '{"A":"اسم معرفہ","B":"اسم مشتق","C":"اسم جامد","D":"ان میں سے کوئی نہیں"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation مسکراہٹ فعل ''مسکرانا'' سے نکلا ہے، اس لیے یہ اسم مشتق ہے۔اسم مشتق وہ ہوتا ہے جو کسی فعل یا صفت سے ماخوذ ہو۔', 0, 0, 0, 1790968559075) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tu_a5aae189c00ea8bc', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_urdu_grammar', 'درج ذیل میں سے کونسا لفظ اسم معرفہ ہے؟', '{"A":"راستہ","B":"جانور","C":"پاکستان","D":"ان میں سے کوئی نہیں"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation اسم معرفہ وہ لفظ ہوتا ہے جس کا خاص طور پر کوئی مخصوص اور معین مفہوم ہو، جیسے "پاکستان" جو ایک مخصوص ملک کا نام ہے۔', 0, 0, 0, 1790968559075) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tu_db37c48884c388cb', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_urdu_grammar', 'مندرجہ ذیل میں سے کون سا لفظ مذکر استعمال ہوتا ہے؟', '{"A":"ملت","B":"وصف","C":"ستائش","D":"محبت"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation وصف عربی نژاد لفظ ہے اور اردو میں مذکر کے طور پر استعمال ہوتا ہے۔باقی الفاظ: محبت، ستائش، ملت اردو میں مونث سمجھے جاتے ہیں۔', 0, 0, 0, 1790968559075) ON CONFLICT(id) DO NOTHING;
