INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tu_220dd9f166793e40', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_urdu_grammar', 'وقف اور سکتہ کے قواعد کو مدنظر رکھتے ہوئے درج ذیل میں سے درست جملہ کون سا ہے؟', '{"A":"باغ میں گلاب موتیے سورج مکھی اور نرگس کے پھول کھلے ہیں۔","B":"باغ میں گلاب، موتیے، سورج مکھی اور نرگس کے پھول کھلے ہیں۔","C":"باغ میں، گلاب موتیے سورج مکھی اور نرگس کے پھول کھلے ہیں۔","D":"ان میں سے کوئی نہیں"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation وقف (،) کا استعمال اشیاء کی فہرست میں درست انداز میں ہوا ہے۔اس سے جملے کی روانی اور مطلب دونوں واضح ہو جاتے ہیں۔', 0, 0, 0, 1790968559075) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tu_36d59f744f64bb36', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_urdu_grammar', 'وہ فعل جس کا فاعل معلوم نہ ہو ـــــــــــــــ کہلاتا ہے؟', '{"A":"فعل مجہول","B":"فعل معروف","C":"فعل مضارع","D":"فعل امر"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation وہ فعل جس میں کام کرنے والا (فاعل) معلوم نہ ہو، فعلِ مجہول کہلاتا ہے۔مثال: "چوری کر لی گئی" — یہاں فاعل معلوم نہیں۔', 0, 0, 0, 1790968559075) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tu_12642e708d1a4a85', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_urdu_grammar', 'ساجد نے گاڑی احتیاظ سے چلائی۔ اس جملے میں مفعول کی نشاندہی کریں؟', '{"A":"ساجد","B":"گاڑی","C":"احتیاط","D":"چلائی"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation جملے میں "گاڑی" وہ چیز ہے جس پر عمل (چلانا) کیا گیا ہے، اس لیے یہ مفعول ہے۔ساجد فاعل ہے، احتیاط حال ہے، اور چلائی فعل ہے۔', 0, 0, 0, 1790968559075) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tu_306a1406ed09f1c7', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_urdu_grammar', 'قواعد کی رو سے ''ہنسی مذاق'' کون سے الفاظ ہیں؟', '{"A":"مہمل الفاظ","B":"ہم معنی الفاظ","C":"حروف جار","D":"مرکب الفاظ"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation ہنسی مذاق دو الفاظ کا مجموعہ ہے، جو مل کر ایک نیا مفہوم پیدا کرتے ہیں۔ایسے الفاظ کو مرکب الفاظ کہا جاتا ہے، جن میں دو یا زیادہ الفاظ مل کر ایک نیا معنٰی بناتے ہیں۔مرکب کی دو قسمیں ہوتی ہیں(1) مرکب ناقص (2) مرکب تام(1) مرکب ناقص وہ مرکب ہے جس سے سننے والے کو پورا مطلب سمجھ میں نہ آئے۔(2) مرکب تام وہ مرکب ہے جس کے سننے سے پورا مطلب سمجھ میں آجائے', 0, 0, 0, 1790968559075) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tu_9d95df205cb71ad4', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_urdu_grammar', 'نظم و ضبط قواعد کی رو سے کونسا مرکب ہے؟', '{"A":"مرکب توصیفی","B":"مرکب عطفی","C":"مرکب اضافی","D":"مرکب شارہ"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation ایسے مرکبات جو معطوف الیہ اور معطوف سے مل کر بنے مرکب عطفی کہلاتے ہیںنظم و ضبط ایک مرکب عطفی ہے کیونکہ دونوں الفاظ کو عطف (اور) کے ذریعے جوڑا گیا ہے۔اس میں دونوں الفاظ آزاد ہوتے ہیں اور ایک دوسرے سے عطف کے ذریعے جڑے ہوتے ہیں۔', 0, 0, 0, 1790968559116) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tu_51bc52c3417ef15f', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_urdu_grammar', 'غزل کے کس شعر میں شاعر اپنا تخلص بیان کرتا ہے؟', '{"A":"مطلع","B":"مقطع","C":"بیت","D":"تمام"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation شعر غزل کے ایک حصے کو کہتے ہیں۔ شعر کی سطر کو مصرع کہا جاتا ہے، اشعار پر مشتمل مجموعہ کو غزل کہتے ہیں ایک شعر میں دو مصرعے ہوتے ہیں۔ پہلے مصرعے کو مصرع اولیٰ اور دوسرے کو مصرع ثانی کہتے ہیں غزل میں موجود اشعار کے مختلف نام ہیں پہلے شعر کو مطلع کہا جاتا ہے جس کے دونوں مصروں میں قافیہ اور ردیف استعمال ہوتا ہے غزل کے آخری شعر کو مقطع کہا جاتا ہے جس کے پہلے مصرعے میں اکثر شاعر اپنا تخلص استعمال کرتے ہیں اور دوسرے مصرعے میں قافیہ کے ساتھ ردیف کا استعمال کیا جاتا ہے مطلع اور مقطع کے درمیان موجود غزل کے تمام اشعار (ہرایک شعر کو) کو بیت کہتے ہیں۔', 0, 0, 0, 1790968559116) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tu_63bdbce58dafee2c', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_urdu_grammar', 'امکان سے امکانات۔ یہ اسم کی کون سی قسم ہے؟', '{"A":"اسم نکرہ","B":"اسم معرفہ","C":"اسم جمع","D":"ان میں سے کوئی نہیں"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation امکان واحد ہے، جبکہ "امکانات" اس کی جمع ہے، جو کہ کثرت کو ظاہر کرتی ہے۔اسم جمع وہ الفاظ ہوتے ہیں جو ایک سے زیادہ اشیاء، افراد یا تصورات کو ظاہر کریں۔', 0, 0, 0, 1790968559116) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tu_8716f852166f1986', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_urdu_grammar', 'قواعد کی رو سے ''مہاراجہ'' کونسا اسم ہے؟', '{"A":"اسم صفت","B":"اسم ذات","C":"اسم مکبر","D":"اسم مصفر"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation مہاراجہ ایک اسم مکبر ہے کیونکہ یہ کسی شخص کی عظمت یا بزرگی کو ظاہر کرتا ہے۔اسم مکبر ایسے الفاظ ہوتے ہیں جو کسی فرد یا چیز کی اہمیت یا شان کو بڑھا چڑھا کر بیان کرتے ہیں۔', 0, 0, 0, 1790968559116) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tu_01c4f6520f216bde', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_urdu_grammar', 'امتحان دیا گیا۔ یہ جملا فعل کی کون سی قسم کا ہے؟', '{"A":"ماضی مطلق","B":"فعل ماضی","C":"فعل مجہول","D":"ان میں سے کوئی نہیں"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation جملہ "امتحان دیا گیا" میں کام کرنے والے (فاعل) کا ذکر نہیں، بلکہ کام (امتحان دیا جانا) پر زور دیا گیا ہے۔ایسے جملے فعل مجہول کہلاتے ہیں کیونکہ ان میں کام کرنے والے کا ذکر نہیں ہوتا۔', 0, 0, 0, 1790968559116) ON CONFLICT(id) DO NOTHING;
