INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tu_4bf1648f10eda588', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_urdu_grammar', 'یہ فیضان نظر تھا یا کہ مکتب کی کرامت تھی سکھائے کس نے اسماعیل کو آداب فرزندی اقبال کے اس شعر میں کون سی صنف ہے؟', '{"A":"مرات النص","B":"تلمیح","C":"لف و نشر","D":"ان میں سے کوئی نہیں"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation تلمیح کے لغوی معنی ہیں اِشارہ کرنا۔ شعری اصطلاح میں تلمیح سے مراد ہے کہ ایک لفظ یا مجموعہ الفاظ کے ذریعے کسی تاریخی'' سیاسی'' اخلاقی یا مذہبی واقعے کی طرف اشارہ کیا جائے۔ تلمیح کے استعمال سے شعر کے معنوں میں وُسعت اور حسن پیدا ہوتا ہے۔ مطالعہ شعر کے بعد پورا واقعہ قاری کے ذہن میں تازہ ہو جاتا ہے۔', 0, 0, 0, 1790968559195) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tu_44e777b909674a18', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_urdu_grammar', 'ٹک ٹک، چھم چھم، ریں ریں، دھگ دھگ وغیرہ الفاظ قواعد کی رو سے کیا ہیں؟', '{"A":"اسم مکبر","B":"اسم آلا","C":"اسم صفت","D":"اسم صوت"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation ٹک ٹک، چھم چھم، ریں ریں، دھگ دھگ وغیرہ الفاظ قواعد کی رو سے اسم صوت ہیں۔', 0, 0, 0, 1790968559195) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tu_8adda6ad9fa6a24d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_urdu_grammar', 'ہر چند اردو میں سب سے سے کم سرمایہ چھوڑا ہے مگر کتنا اونچا مقام پایا۔ رشید احمد صدیقی کا یہ جملہ کس مزاح نگار کے بارے میں ہے؟', '{"A":"ابن انشاء","B":"شوکت تھانوی","C":"پطرس بخاری","D":"مرزا فرحت اللہ بیگ"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation ہر چند اردو میں سب سے سے کم سرمایہ چھوڑا ہے مگر کتنا اونچا مقام پایا۔ رشید احمد صدیقی کا یہ جملہ پطرس بخاری مزاح نگار کے بارے میں ہے۔', 0, 0, 0, 1790968559195) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tu_72a2819cab7bf1d4', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_urdu_grammar', 'وہ اسم جو خود کسی سے نہ بنا ہو اور نہ ہی اس سے دوسرے الفاظ بنائے جا سکتے ہوں؟', '{"A":"اسم صفت","B":"اسم مصدر","C":"اسم مشتق","D":"اسم جامد"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation اسم جامد وہ اسم ہوتا ہے جو کسی دوسرے لفظ سے نہیں بنا ہوتا اور اس سے مزید الفاظ نہیں بنائے جا سکتے۔جیسے میز، کرسی، اور کتاب', 0, 0, 0, 1790968559195) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tu_16a693e7b15a95c5', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_urdu_grammar', 'کون سا جملہ درست ہے؟', '{"A":"برائے مہربانی کل ضرور آئیں","B":"برائے مہربانی کرکے کل ضرور آئیں","C":"براہ مہربانی کل ضرور آئیں","D":"براہ مہربانی کرکے کل ضرور آئیں"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation براہِ مہربانی لکھا کریں نہ کہ براے مہربانی۔', 0, 0, 0, 1790968559195) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tu_9a625c50afcd7b50', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_urdu_grammar', 'قواعد کا وہ حصہ، جس میں مرکب جملوں اور عبارتوں سے بحث کی جاتی ہے، وہ  کیا کہلاتا ہے؟', '{"A":"صرف","B":"نحوٍ","C":"قواعد","D":"املاانشا"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation علم نحو قواعد کی وہ قسم ہے جس میں مرکب جملوں اور عبارتوں سے بحث کی جاتی ہے۔اس میں جملوں کو جوڑنا ، توڑنا اور ان کا آپس میں تعلق معلوم کرنا سیکھا جاتا ہے۔علم نحو میں ماہر شخص کو نحوی کہا جاتا ہے۔صرف، قواعد کا وہ حصہ ہے جس میں جملوں اور مرکبات کی بجائے، فقط الفاظ کے بارے میں بحث کی جاتی ہے؛اُن کی ساخت، بناوٹ اور معانى کی وضاحت کی جاتی ہے اور صرف الفاظ کو موضوع بحث بنایا جاتا ہے۔', 0, 0, 0, 1790968559195) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tu_5989c67eabb772a1', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_urdu_grammar', 'وہ صبح اور وہ چھاؤں ستاروں کی اور وہ نور دیکھے تو غش کرے ارنی گوئی اوج طور۔ اس شعر میں علم بیان کی کون سی صورت آئی ہے؟', '{"A":"تشہبہ","B":"استعارہ","C":"مجاز مرسل","D":"کنایہ"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation کسی ایک چیز کو کسی خاص صفت کے اعتبار سے یا مشترک خصوصیت کی بنا پر دوسری کی مانند قرار دے دیا جائے تو اسے تشبیہ کہتے ہیں۔', 0, 0, 0, 1790968559235) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tu_1934e696a38d60a9', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_urdu_grammar', 'ثجھے اس قوم نے پالا ہے آغوش محبت میں کچل ڈالا تھا جس نے پاؤں میں تاج سر دارا اقبال کے اس شعر میں کونسی صفت استعمال ہوئی ہے؟', '{"A":"تلمیح","B":"تشبیہ","C":"استعارہ","D":"ان میں سے کوئی نہیں"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation تلمیح: اس شعر میں ''تاجِ سرِ دارا'' فارسی سلطنت کے زوال اور مسلمانوں کے عروج کی تاریخی داستان کی طرف اشارہ ہے۔Last updated by NS on 06 May 2026', 0, 0, 0, 1790968559235) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tu_936ec1fd77111a33', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_urdu_grammar', 'اسم علم کی رو سے"شمس العلماء" کیا ہے؟', '{"A":"خطاب","B":"کنیت","C":"لقب","D":"None"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation شمس العلماء کا خطاب درج ذیل لوگوں کو ملا تھا۔ موالانا الطاف حسین حالی مولانا ابوالکلام آزاد ڈپٹی نذیر احمد مولانا شبلی نعمانی*********RY 13-01-2023', 0, 0, 0, 1790968559235) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tu_15c36c3eadd22358', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_urdu_grammar', 'ڈوبتے کو تنکے کا سہارا قواعد کی رو سے کیا ہے؟', '{"A":"محاورہ","B":"کہاوت","C":"قول","D":"None"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation یہ کہاوت ایسے موقع پر بولی جاتی ہے جب کسی شخص کو بھاری نقصان ہونے کے بعد تھوڑی بہت امداد کا سہارا مل جائے*****RY 11-10-2022ND27-4-2023', 0, 0, 0, 1790968559235) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tu_8f7c25fe01d6df07', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_urdu_grammar', 'اسلم بیمار ھے کس قسم کا جملہ ھے؟', '{"A":"اسمیہ","B":"فعلیہ","C":"دونوں","D":"حروف ندایا"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation جملہ اسمیہ کی تعریف: جملہ اسمیہ میں مسندالیہ ہمیشہ اسم ہوتا ہے جبکہ مسند کبھی اسم ہوتا ہے اور کبھی فعل ہوتا ہے- جس جملے مسندالیہ اور مسند دونوں اسم ہوں اور اس میں فعل ناقص آئے تو اسے جملہ اسمیہ کہتے ہیں-مثال کے طور پر ” علم بڑی دولت ہے” راشد بیمار ہے-پہلے جملے میں علم اور دولت دونوں اسم ہیں اور دوسرے جملہ میں راشد اور بیمار دونوں اسم ہیں۔اسمیہ کے مسندالیہ کو مبتدا اؤر مسند کو خبر کہتے ہیں-جملہ اسمیہ کے اجزاء: مبتدا, خبر، اور فعل ناقص۔', 0, 0, 0, 1790968559235) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tu_1361a89b22683784', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_urdu_grammar', 'لفظ پہناوا قواعد کی رو سے کیا ہے؟', '{"A":"اسم جامد","B":"اسم مصدر","C":"فعل متعدی","D":"اسم حاصل مصدر"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation مصدرمصدر ایسا اسم ہے جو خود تو کسی اسم سے نہ بنا ہو مگر اس سے کئی اسم بن سکیں۔ مصدر کی پہچان یہ ہے کہ اس کے آخر میں "نا" آتا ہے۔ مثلاً جانا ۔ پڑھنا ۔ سونا وغیرہ۔اسم حاصل مصدرایسا اسم جو مصدر سے بنے، اسم حاصل مصدر کہلاتا ہے۔ مثلاً پڑھنا سے پڑھائی، پڑھنے والا وغیرہ۔Last updated question by NA on 07 May 2026', 0, 0, 0, 1790968559235) ON CONFLICT(id) DO NOTHING;
