INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tu_4217125ee8ada96d', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_urdu_grammar', 'قوتِ عشق سے ہر پست کو بالا کر دے دہر میں اسمِ محمد سے اجالا کردے یہ شعر کس کا ہے؟', '{"A":"حفیظ جھالندری","B":"علامہ اقبال","C":"میر انیس","D":"الطاف حسین حالی"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation قوتِ عشق سے ہر پست کو بالا کر دےدہر میں اسمِ محمد سے اجالا کردے(صلی اللہ علیہ والہ وسلم)ہو نہ یہ پھول تو بلبل کا ترنم بھی نہ ہوچمنِ دہر میں کلیوں کا تبسم بھی نہ ہوخیمہ افلاک کا ایستادہ اس نام سے ہےنبضِ ہستی تپش آمادہ اسی نام سے ہےدشت میں، دامنِ کہسار میں ، میدان میں ہےبحر میں،‌موج کی آغوش میں ، طوفان میں ہےچین کے شہر مراکش کے بیابان میں ہےاور پوشیدہ مسلمان کے ایمان میں ہےچشم افلاک یہ نظارہ ابد تک دیکھےرفعتِ شان رفعنا لک ذکرک دیکھے', 0, 0, 0, 1790968559235) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tu_d93794607551b97e', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_urdu_grammar', 'کھانا کھایا گیا فعل کی کونسی قسم ہے؟', '{"A":"فعل معروف","B":"فعل جاری","C":"فعل مجہول","D":"فعل حال مطلق"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation جب فعل کا فاعل معلوم نہ ہو اور مفعول اس کا قائم مقام ہو تو اسے فعل مجہول کہتے ہیںوہ فعل جس کا فاعل معلوم نہ ہو فعل معروف کہلاتا ہے۔', 0, 0, 0, 1790968559270) ON CONFLICT(id) DO NOTHING;
