INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tu_6b150f245604f41b', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_urdu_grammar', 'حرف یا حروف کا وہ مجموعہ جو کسی با معنی لفظ کے شروع میں لگنے سے نیا لفظ بن جائے، کیا کہلاتا ہے؟', '{"A":"سابقہ","B":"لاحقہ","C":"مترادف","D":"مرکب"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation کسی لفظ کے شروع میں کوئی علامت لگا کر اس سے ایک نیا لفظ بنالیا جاتا ہے۔ اس علامت کو "سابقہ" کہتے ہیں۔جیسے کہ "ادب" کے آگے "بے" لگا کر "بےادب" اور "سمجھ" کے آگے "نا" لگا کے "ناسمجھ" بنالیا جاتا ہے اور "مول" سے "انمول"۔۔۔۔اس مثال میں "بے" "نا" اور "ان" سابقے ہیں۔کسی لفظ کے آخر میں کوئی علامت لگا کر اس سے نیا لفظ بنایا جائے تو اسے "لاحقہ" کہا جاتا ہے۔جیسے "ضرورت" کے آخر میں "مند" لگا کر "ضرورتمند" اور "درد" کے آخر میں "ناک" لگا کر "دردناک"۔۔۔یہاں "مند" اور "ناک" لاحقے ہیں۔*******', 0, 0, 0, 1790968559306) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tu_d3f7ce8cb4ffab7b', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_urdu_grammar', 'ماں کہتی ہے میرا چاند آیا قواعد کی رو سے کیا ہے؟', '{"A":"محاورہ","B":"روزمرہ","C":"مجاز مرسل","D":"تشبیہ","E":"استعارہ"}', 'E', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation علم بیان کی اصطلاح میں حقیقی اور مجازی معنوں کے درمیان تشبیہ کا علاقہ ہونا استعارہ کہلاتا ہے۔ یعنی حقیقی معنی کا لباس عاریۃَ َ لے کر مجازی معنوں کو پہنانا۔ مثلا نرگس کہہ کر آنکھ مراد لینا۔ استعارہ اور تشبیہ میں یہ فرق ہے کہ استعارہ تشبیہ سے زیادہ بلیغ ہوتا ہے۔ تشبیہ میں ایک چیز کو دوسری جیسا قرار دیا جاتا ہے جب ان میں کوئی صفت یا خوبی مشترک ہو لیکن استعارے میں ایک چیزکوہوبہودوسری چیزمان لیا جاتاہے۔', 0, 0, 0, 1790968559306) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tu_d438334edacc66b7', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_urdu_grammar', 'غزل کے آخری شعر جس میں تخلص نہ ہواسے کیا کہتےہیں ۔', '{"A":"مطلع","B":"مقطع","C":"شعر اول","D":"آخری شعر"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation غزل کے آخری شعر کو مقطع کہا جاتا ہے جس کے پہلے مصرہ میں اکثر شاعر اپنا تخلص استمال کرتےہیں اور دوسرے مصرہ میں قافیہ کے ساتھ ردیف کا استمال کیا جاتا ہے', 0, 0, 0, 1790968559306) ON CONFLICT(id) DO NOTHING;
