INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tu_b9872f692e0b7e0b', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_urdu_grammar', 'وہ اسم جس سے دوسرے بہت سے الفاظ تو مقررہ قاعدوں کے مطابق بنتے ہوں مگر وہ خود کسی سے نہ بنا ہو ــــــــ کہلاتا ہے؟', '{"A":"کوئی بھی نہیں","B":"اسم مشتق","C":"اسم مصدر","D":"اسمِ جامد"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation وہ اسم جس سے دوسرے بہت سے الفاظ تو مقررہ قاعدوں کے مطابق بنتے ہوں مگر وہ خود کسی سے نہ بنا ہو اسم مصدر کہلاتا ہے', 0, 0, 0, 1790968559450) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tu_4279bbf99c2e78ff', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_urdu_grammar', 'نیم بیداری اور بیماری قواعد کی رو سے کیا ھے ؟', '{"A":"اسم کفیت","B":"اسم علم","C":"اسم اشارہ","D":"None"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation اسم کیفیت وہ اسم ہے جواسم کی کسی کیفیت کو ظاہر کرے اور قوائد کے مطابق اسم سے حاصل کیا گیا ہو۔', 0, 0, 0, 1790968559450) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tu_4266be595dc41164', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_urdu_grammar', 'وہ مصدر جس سے بننے والے فعل کے لیے مفعول کی بھی ضرورت ہوتی ہے ــــــ کہلاتا ہے؟', '{"A":"لازم مصدر","B":"اصلی مصدر","C":"ان میں سے کوئی بھی نہیں","D":"متعدی مصدر"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation اسم مصدر اسم کی ایک قسم ہے۔ اسم مصدر ایسا اسم ہوتا ہے جو خود تو کسی اسم سے نہیں بنتا لیکن اس سے مقررہ قاعدوں کے مطابق کئی الفاظ بنائے جا سکتے ہوں مثلا پڑھنا سے پڑھو، دیکھنا سے دیکھو، بڑھانا سے بڑھائو، بنانا سے بناوٹ، سونگھنا سے سونگھو وغیرہ اسم مصدر کی بلحاظ بناوٹ درج ذیل اقسام ہیں۔ مصدر اصلی یا مصدر وضعی، مصدر جعلی یا مصدر مرکب اسی طرح مصدر کی بلحاظ معنی درج ذیل اقسام ہیں۔ مصدر لازم، مصدر متعدی۔', 0, 0, 0, 1790968559450) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tu_923401ee7e777ae6', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_urdu_grammar', 'وہ مصدر جس سے بننے والے فعل کے لیے صرف فاعل کی ضرورت ہوتی ہے ـــــــ کہلاتا ہے؟', '{"A":"لازم مصدر","B":"اصلی مصدر","C":"ان میں سے کوئی بھی نہیں","D":"متعدی مصدر"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation وہ مصدر جس سے بننے والے فعل کے لیے صرف فاعل کی ضرورت ہوتی ہے ـ لازم مصدرکہلاتا ہے', 0, 0, 0, 1790968559481) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tu_6f7fd2a2b0f252e6', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_urdu_grammar', 'وہ ضمیر جو کسی شخص کے لیے استعمال ھو کیا کھلاتا ھے؟', '{"A":"ضمیر  موصولہ","B":"ضمیر شخصی","C":"ضمیر موصول","D":"ضمیر  استفھامیہ"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation وہ ضمیر جو کسی شخص کے لیے استعمال کیا جائے، مثلا: وہ میں، ہم ،آپ، ان،انہوں وغیرہ', 0, 0, 0, 1790968559481) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tu_d831ce18667cf337', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_urdu_grammar', 'کیوں، کیسے، کب۔ اسم نکرہ کے مطابق یہ ــــــــــــــــــــــــ ہیں۔', '{"A":"اسم معرفہ","B":"اسم جامد","C":"اسم استفہام","D":"اسم ذات"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation وہ الفاظ جو سوال پوچھنے کیلئے استعمال ہوں ان کو استفہام کہا جاتا ہے۔', 0, 0, 0, 1790968559481) ON CONFLICT(id) DO NOTHING;
