INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tu_1a3b5b1c60846622', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_urdu_poetry', 'وہ طویل نظم جس میں کوئی قصہ، کہانی، جھنگ کے حالات یا فلسفے کی کوئی لمبی چوڑی بات بیان کی گئی ہو۔ اس نظم کو کیا کہتے ہیں؟', '{"A":"مثنوی","B":"داستان","C":"مرثیہ","D":"ان میں سے کوئی نہیں"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation مثنوی ایک طویل نظم ہوتی ہے جس میں کوئی قصہ، عشق، تصوف یا فلسفہ نظم کی صورت میں بیان کیا جاتا ہے۔اس کی خصوصیت یہ ہے کہ ہر شعر کے دونوں مصرعے ہم قافیہ ہوتے ہیں۔Last verified on 08-08-2026', 0, 0, 0, 1790968559547) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tu_c9c0ebe470246bf9', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_urdu_poetry', 'شاعری میں ابتذال سے کیا مراد ہے؟', '{"A":"تضاد","B":"لف و نشر","C":"عامیانہ","D":"ان میں سے کوئی نہیں"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation شاعری میں ابتذال سے عامیانہ مراد ہے۔', 0, 0, 0, 1790968559547) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tu_266e59267a0ae5da', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_urdu_poetry', 'حافظ محمود شیرانی کے مطابق اردو کا پہلا شاعر کون ہے؟', '{"A":"مسعود سعد سلیمان","B":"قلی قطب شاہ","C":"امیر خسرو","D":"ان میں سے کوئی نہیں"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation حافظ محمود شیرانی کے مطابق اردو کا پہلا شاعر مسعود سعد سلیمان ہے۔', 0, 0, 0, 1790968559547) ON CONFLICT(id) DO NOTHING;
