INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tu_cf25942a29f3596c', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_urdu_poetry', 'شعر کے آخر میں آنے والا ایک لفظ یا کئی الفاظ جو وزن اور آواز میں یکساں، مگر معنی کے اعتبار سے جدا ہوں، کیا کہلاتے ہیں؟', '{"A":"ردیف","B":"قافیہ","C":"مقطع","D":"ان  میں سے کوئی نہیں"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation شعر کے آخر میں آنے والے ایسے ہم آواز اور ہم وزن الفاظ جو معنی کے اعتبار سے مختلف ہوں، قافیہ کہلاتے ہیں۔ قافیہ کی اہم خصوصیاتہم آہنگی: آواز اور وزن میں یکساں ہوتے ہیں۔معنی: ایک دوسرے سے مختلف معنی رکھتے ہیں۔مقام: عام طور پر ردیف سے پہلے آتے ہیں۔Last updated 25-07-2026 by NA', 0, 0, 0, 1790968559547) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tu_c2bcad2842a8cac8', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_urdu_poetry', 'شاعرِ انقلاب کس شاعر کو کہا جاتا ہے؟', '{"A":"جوش ملیح آبادی","B":"احسان دانش","C":"میر تقی میر","D":"ان میں سے کوئی نہیں"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation جوش ملیح آبادی کو انقلابی خیالات اور جوشیلی شاعری کی وجہ سے "شاعرِ انقلاب" کہا جاتا ہے۔ان کی شاعری میں آزادی، بغاوت، اور قومی غیرت کے جذبات نمایاں ہوتے ہیں۔Last verified on 03-06-2026', 0, 0, 0, 1790968559547) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tu_634422ec23a7a974', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_urdu_poetry', 'نقش فریادی کس کا شعری مجموعہ ہے؟', '{"A":"ناصر کاظمی","B":"فیض احمد فیض","C":"منیر نیازی","D":"احمد ندیم قاسمی"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation نقش فریادی فیض احمد فیض کا پہلا شعری مجموعہ ہے۔یہ 1941ء میں شائع ہوا اور فیض کی ابتدائی شاعری کا نمائندہ ہے۔اس میں رومان اور انقلابی جذبات کا خوبصورت امتزاج ملتا ہے۔Last verified on 03-06-2026', 0, 0, 0, 1790968559547) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tu_e653ade9ef170bee', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_urdu_poetry', 'قتلِ حسین اصل میں مرگِ یزید ہے اسلام زندہ ہوتا ہے ہر کربلا کے بعد۔ شاعر کا نام بتائیں؟', '{"A":"علامہ اقبال","B":"حالی","C":"محمد علی جوہر","D":"غالب"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation قتلِ حسین اصل میں مرگِ یزید ہے اسلام زندہ ہوتا ہے ہر کربلا کے بعد۔ یہ مشہور شعر محمد علی جوہر کا ہے۔اس شعر میں واقعۂ کربلا کی عظمت اور حق کی دائمی فتح کو بیان کیا گیا ہے۔یہ شعر اردو ادب اور اسلامی تاریخ میں بہت مقبول اور مؤثر سمجھا جاتا ہے۔Last verified on 03-06-2026', 0, 0, 0, 1790968559547) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tu_156fc3a7cc8d6533', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_urdu_poetry', 'شہاب نامہ کس مصنف کی آپ بیتی ہے؟', '{"A":"قدرت اللہ شہاب","B":"قتیل سفائی","C":"جوش ملیح آبادی","D":"غالب"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation شہاب نامہ قدرت اللہ شہاب کی خودنوشت ہے۔اس میں ان کے سرکاری تجربات اور زندگی کے اہم واقعات بیان کیے گئے ہیں۔یہ اردو ادب کی مشہور اور اہم سوانحی کتابوں میں شمار ہوتی ہے۔Last verified on 02-06-2026', 0, 0, 0, 1790968559586) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tu_d08cdcb8f071a3a6', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_urdu_poetry', 'ایسی نظم جس کے ہر بند میں مصرع یا شعر چار بار دہرایا جائے، اصطلاح میں کیا کہتے ہیں؟', '{"A":"ترجیع بند","B":"ترکیب بند","C":"مخمس","D":"ان میں سے کوئی نہیں"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation ایسی نظم جس کے ہر بند کے آخر میں ایک ہی مصرع یا شعر بار بار دہرایا جائے اسے ترجیع بند کہتے ہیں۔اس تکرار سے نظم میں تاکید، موسیقیت اور اثر انگیزی پیدا ہوتی ہے۔یہ اردو شاعری کی ایک اہم بندش ہے جس میں ہر بند ایک ہی مرکزی خیال سے جڑا رہتا ہے۔Last verified on 02-06-2026', 0, 0, 0, 1790968559586) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tu_ee85be35e9189d0a', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_urdu_poetry', 'مسدس کے ہر بند میں کتنے مصرعے ہوتے ہیں؟', '{"A":"چار","B":"پانچ","C":"چھ","D":"ان میں سے کوئی نہیں"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation مسدس کے ہر بند میں چھ (6) مصرعے ہوتے ہیں۔ ساخت: اس کے پہلے چار مصرعے ہم قافیہ اور ہم ردیف ہوتے ہیں، جبکہ آخری دو مصرعے (جنہیں ''بیت'' کہا جاتا ہے) الگ قافیہ رکھتے ہیں۔استعمال: یہ صنفِ شاعری طویل نظمیں، مرثیے اور قومی و اخلاقی موضوعات کے لیے استعمال ہوتی ہے۔مثال: مشہور مثال مولانا حالی کی "مسدسِ حالی" ہے۔', 0, 0, 0, 1790968559586) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tu_c3a084f56e858efe', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_urdu_poetry', 'جب کسی لفظ کو حقیقی معنوں کی بجائے مجازی معنوں میں استعمال کیا جائے اور اس میں تشبیہ کے علاؤہ کوئی اور تعلق پایا جائے تو اسے کیا کہتے ہیں؟', '{"A":"استعارہ","B":"مجاز مرسل","C":"تشبیہ","D":"ان میں سے کوئی نہیں"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation علم بیان کی اصطلاح میں، جب کوئی لفظ اپنے حقیقی معنوں کی بجائے مجازی معنوں میں استعمال ہو اور ان کے درمیان تشبیہ کے علاوہ کوئی اور تعلق (جیسے جزو و کل، ظرف و مظروف) پایا جائے تو اسے مجازِ مرسل کہتے ہیں۔ یہ استعارہ سے مختلف ہے کیونکہ اس میں مشابہت ضروری نہیں ہوتی۔', 0, 0, 0, 1790968559586) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tu_56b58eb6e77872d8', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_urdu_poetry', 'غزل کا پہلا مصرعہ جس کے دونوں مصرعے ہم قافیہ اور ہم ردیف ہوں ـــــــــــــــــــ کہلاتا ہے۔', '{"A":"پہلامشعر","B":"مطلع","C":"موصول","D":"مقطع"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation غزل کا پہلا مصرعہ جس کے دونوں مصرعے ہم قافیہ اور ہم ردیف ہوں، مطلع کہلاتا ہے، جس کے بعد آنے والے شعر کو حسنِ مطلع اور آخر میں تخلص والے شعر کو مقطع کہا جاتا ہے. زندگی اگر تیری مختصر ہےتو کیا ہے اب مرنے سے ڈر ہے', 0, 0, 0, 1790968559586) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tu_d3ce29b2816cede7', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_urdu_poetry', 'مسدس حالی کا اصل نام کیا ہے؟', '{"A":"مدوجزراسالم","B":"شاہ نامہ اسالم","C":"ضرب کلیم","D":"ارمغا ن حجاز"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation ردو شاعری میں مولانا حالی کا اعلیٰ ترین کارنامہ ان کی طویل نظم ”مدوجزر اسلام“ ہے جو عام طور پر ”مسدس حالی“ کے نام سے مشہور ہوئی۔مسدس حالی کے کل 294 بند ہیںLast update 0n 21-07-2026 by NA', 0, 0, 0, 1790968559586) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tu_6e08a1712468d8fa', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_urdu_poetry', 'مسجد قرطبہ کس کی نظم ہے؟', '{"A":"علامہ اقبال","B":"حالی","C":"غالب","D":"ان میں سے کوئی نہیں"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation لامہ محمد اقبال نے اپنی وفات سے 5 سال قبل 1933 میں اپنی مشہور نظم مسجدِ قرطبہ میں مسجدِ قرطبہ کو مندرجہ بالا انداز میں بیان کیا تھا۔ نظم کے عنوان کے نیچے عبارت میں لکھا ہے کہ یہ نظم اسپین کے شہر قرطبہ میں تحریر کی گئی تھی۔', 0, 0, 0, 1790968559586) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tu_2f6cf2543a07d8b8', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_urdu_poetry', 'غزل کا دوسرا شعر جس کے دونوں مصرعے ہم قافیہ و ہم ردیف ہوں، کہلاتا ہے؟', '{"A":"مطلع","B":"بیت","C":"غزل","D":"ان میں سے کوئی نہیں"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation غزل کا دوسرا شعر جس کے دونوں مصرعے مطلع کی طرح ہم قافیہ و ہم ردیف ہوں، اسے "حسنِ مطلع" کہتے ہیں، اور اگر ایک غزل میں دو مطلعے ہوں تو دوسرے کو یہ نام دیا جاتا ہے.', 0, 0, 0, 1790968559586) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tu_589bda8e3d44aee7', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_urdu_poetry', 'نظم آدمی نامہ کس نے لکھا؟', '{"A":"علامہ اقبال","B":"مرزا غالب","C":"نظیر اکبر آبادی","D":"میر انیس"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation آدمی نامہ مشہور نظم ہے جو نظیر اکبر آبادی نے لکھی۔اس نظم میں انہوں نے مختلف قسم کے انسانوں کا ذکر بڑے دل چسپ اور حقیقت پسند انداز میں کیا ہے۔', 0, 0, 0, 1790968559633) ON CONFLICT(id) DO NOTHING;
