INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tu_e19d65e2b96b2785', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_urdu_poetry', 'اگر کسی لفظ کو حقیقی معنوں کی بجائے مجازی معنوں میں اس طرح استعمال کی جائے کہ حقیقی اور مجازی معنی میں ______ کے علاوہ کوئی اور تعلق پایا جائے تو اسے مجاز مرسل کہتے ہیں۔', '{"A":"تشبیہ","B":"اسم","C":"فعل","D":"ان میں سے کوئی نہیں"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation مجاز مرسل میں لفظ اپنے حقیقی معنی کے بجائے کسی اور متعلقہ معنی میں استعمال ہوتا ہے، لیکن اس میں تشبیہ کا عنصر شامل نہیں ہوتا۔مثال: "بادشاہ کا حکم آیا" یہاں بادشاہ سے مراد اس کا حکم ہے، یعنی سبب اور مسبب کا تعلق پایا جاتا ہے۔', 0, 0, 0, 1790968559633) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tu_631963f1b0eccb87', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_urdu_poetry', 'ایک تھا لڑکا ٹوٹ بٹوٹ کس کی نظم ہے؟', '{"A":"حبیب جالب","B":"صوفی غلام مصطفیٰ تبسم","C":"احمد تبسم","D":"احمد فراز"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Ghulam Mustafa Tabassum, was a poet. His pen name was Tabassum. Born: August 4, 1899, Amritsar, IndiaDied: February 7, 1978, LahoreEducation: Forman Christian College, University, LahoreAwards: Pride of Performanceصوفی غلام مصطفٰی تبسم اردو، پنجابی اور فارسی زبانوں کے شاعر تھے۔ آپ بچوں کے مقبول ترین شاعر تھے۔', 0, 0, 0, 1790968559633) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tu_ab0f54b272deb425', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_urdu_poetry', 'جب کسی لفظ کو حقیقی معنوں کے بجائے مجازی معنوں میں اصل استعمال کیا جائے کہ حقیقی اور مجازی معنوں میں تشبیہہ کا تعلق موجود ہو تو اسے گرائمر کی رو سے کیا کہا جائے گا؟', '{"A":"تشبیہہ تام","B":"تشبیہہ مرکب","C":"استعارہ","D":"مستعارہ"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation استعارہ ایسی بلاغتی صنعت ہے جس میں تشبیہ کے ارکان میں سے اکثر کو حذف کر کے صرف مشبہ بہ کو استعمال کیا جاتا ہے۔اس میں لفظ اپنے مجازی معنی میں استعمال ہوتا ہے، لیکن پس منظر میں تشبیہ کا تعلق موجود ہوتا ہے۔', 0, 0, 0, 1790968559633) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tu_a8aa0a142b5ed218', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_urdu_poetry', 'علامہ اقبال کی مشہور نظم "خضر راہ" ان کے کس مجموعہ کلام میں ہے؟', '{"A":"اسرار خودی","B":"بال جبریل","C":"ضرب کلیم","D":"بانگِ درا"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation نظم "خضرِ راہ" علامہ اقبال کے پہلے اردو مجموعہ بانگِ درا میں شامل ہے۔اس نظم میں علامہ اقبال نے معاشرتی، سیاسی اور فکری مسائل پر رہنمائی کے لیے حضرت خضرؑ کا تصور پیش کیا ہے۔', 0, 0, 0, 1790968559633) ON CONFLICT(id) DO NOTHING;
