INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tu_f0c6112d1a92fa31', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_urdu_poetry', 'دیوار کیا گری مرے خستہ مکان کی لوگوں نے میرے صحن میں رستے بنا لیے۔ یہ شعر کس کا ہے؟', '{"A":"غالب","B":"سبط علی صبا","C":"فیض احمد فیض","D":"ان میں سے کوئی نہیں"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation سید سبط علی صبا 38 برس پہلے 14؍ مئی 1980ء کوصرف ساڑھے چوالیس برس کی عمر میں حرکت قلب بند ہوجانے سے انتقال کرگئے ۔۔ وہ 11نومبر 1935ء کو کوٹلی لوہاراں ،ضلع سیالکوٹ میں پید اہوئے۔ ابتدائی تعلیم رڑکی(بھارت) اور سیالکوٹ سے حاصل کی۔ پہلے پاک فوج اور پھر پاکستان آرڈیننس فیکٹریز، واہ کینٹ میں ملازم رہے۔ ان کے انتقال کے بعد ’’طشت مراد‘‘ کے نام سے ان کا شعری مجموعہ 1986ء میں چھپا۔ حالانکہ انہوں نے خود مجموعۂ کلام کا نام ’’ ابرِ سنگ‘‘ طے کیا تھا۔ اس نام سے بعد میں شائع بھی ہوا۔', 0, 0, 0, 1790968559827) ON CONFLICT(id) DO NOTHING;
