INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tu_e1b14127bc75cd2b', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_urdu_literature', 'آپ بتا سکتے ہیں کہ شہرہ آفاق افسانہ نگار غلام عباس کہاں پیدا ہوئے تھے', '{"A":"امر تسر","B":"آگرہ","C":"دھلی","D":"لکھنو"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation غلام عباس 17 نومبر 1909ء میں امر تسر (چند محققین کی رائے میں 1907) میں پیدا ہوئے۔غلام عباس 2 نومبر 1982ء کو کراچی میں وفات پاگئے اور سوسائٹی کے قبرستان میں آسودہ خاک ہوئے۔ناولٹ گوندنی والا تکیہ، 1936ء،جزیرہ سخن وراں، 1941ء،دھنک، 1969ء بچوں کا ادب الحمرا کے افسانے، 1931ء،چاند تارا (نظمیں)،،ننھی کی گڑیا، 1936ء تراجم جلا وطن، از لیو ٹالسٹائی،بے چارہ سپاہی ،صدر ایوب کی کتاب فرینڈ ناٹ ماسٹرز کا ترجمہ، جس رزق سے آتی ہو پرواز میں کوتاہی کے نام سے', 0, 0, 0, 1790968560264) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tu_5a81a1809b764a11', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_urdu_literature', 'اردو کا پہلا افسانہ نگار کون ہے؟', '{"A":"پریم چند","B":"سجاد حیدر یلدرم","C":"اعظم کریوی","D":"انتظار حسین"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation ڈاکٹر معین الدین نے سجاد حیدر یلدرم کو پہلا افسانہ نگار قرار دایا ہے۔جبکہ بعض کے خیال میں پریم چند پہلے افسانہ نگار ہیں۔سجاد حیدر یلدرم اور پریم چند اردو افسانے کے دو اہم نام اور ستون ہیں۔یہ دو نام ہیں بلکہ دورجحانات ہیں ایک رومانیت کا اور دوسرا حقیقت نگاری کا۔یلدرم کا رومانی مزاج ہے اور پریم چند کی حقیقت نگاری کا رجحان غالب ہے۔زیادہ اولیت اور آراء پریم چند کے حق میں ہے۔', 0, 0, 0, 1790968560264) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tu_592767083f561cb5', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_urdu_literature', 'افسانہ ہمارے ہاں کس زبان کے ادب سے آیا؟', '{"A":"فرانسیسی","B":"انگریزی","C":"جرمنی","D":"چینی"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation افسانہ ادب کی نثری صنف ہے۔ لغت کے اعتبار سے افسانہ جھوٹی کہانی کو کہتے ہیں لیکن ادبی اصطلاح میں یہ لوک کہانی کی ہی ایک قسم ہے۔ ناول زندگی کا کُل اور افسانہ زندگی کا ایک جز پیش کرتا ہے۔ افسانہ دراصل ایک ایسا قصہ ہے جس میں کسی ایک واقعہ یا زندگی کے کسی اہم پہلو کو اختصاراً اور دلچسپی سے تحریر کیا جاتا ہے ۔اس کی ترتیب میں اجزائے ترکیبی کا بہت زیادہ عمل دخل رہتا ہے اور ان میں سے وحدت تاثر کو ذیادہ اہمیت حاصل ہے۔', 0, 0, 0, 1790968560264) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tu_375e5ff832548d38', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_urdu_literature', 'الطاف حسین حالی کی تصنیف ہے؟', '{"A":"جواب شکوہ","B":"مسدّس","C":"شکوہ","D":"بانگ درا"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation مسدس چھ مصرعوں کے ایک بند پر مشتمل شاعری کو کہتے ہیں۔ اس کے پہلے چار مصرعے، ہم قافیہ و ہم ردیف ہوتے ہیں۔ پانچواں اور چھٹا مصرع ہم قافیہ و ہم ردیف ہوتے ہیں۔ طویل اور مسلسل منظومات کے لیے اس کا استعمال بہت ہوا ہے۔ اردو شاعری میں مولانا حالی کا اعلیٰ ترین کارنامہ ان کی طویل نظم ”مدوجزر اسلام“ ہے جو عام طور پر ”مسدس حالی“ کے نام سے مشہور ہوئی۔ یہ نظم اس قدر مقبول ہوئی کہ اس نے مقبولیت اور شہرت کے اگلے پچھلے تمام ریکارڈ توڑ ڈالے۔ کہا جاتا ہے کہ کئی سال تک برصغیر کے طول و عرض میں جو کتاب قرآن کریم کے بعد سب سے زیادہ شائع ہوئی وہ ”مسدس حالی“ تھی۔', 0, 0, 0, 1790968560264) ON CONFLICT(id) DO NOTHING;
