INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tu_c4ffc19593b0797b', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_urdu_poets', 'سرسید احمد خان کے گلے میں اکثر ایک رومال بندھا رہتا تھا کیا آپ بتا سکتے ہیں کیوں', '{"A":"گلہ دکھتا تھا اسلیئے","B":"فیشن کیلئے","C":"گلے کی رسولی کی بدنمائی چھپانے کیلئے","D":"عا دتاً"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation سید احمد بن متقی خان (17 اکتوبر 1817ء – 27 مارچ 1898ء) المعروف سر سید انیسویں صدی کا ایک ہندوستانی مسلم نظریۂ عملیت کا حامل ، مصلح اور فلسفی تھے۔ آپ کو برصغیر میں مسلم قوم پرستی کا سرخیل مانا جاتا ہے اور دو قومی نظریہ کا خالق تصور کیا جاتا ہے جو کے آگے چل کر تحریک پاکستان کی بنیاد بنی۔ بقول مولانا شبلی نعمانی، ”اردو انشاءپردازی کا جو آج انداز ہے اُس کے جد امجد اور امام سرسید تھے“۔سرسید احمد خان کو اردو مضمون نگاری کا بانی تصور کیا جاتا ہے۔"', 0, 0, 0, 1790968560345) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tu_890e20ea605b7d89', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_urdu_poets', 'حالی کا اصل نام کیا ہے', '{"A":"یحیےٰ امان","B":"ثناءﷲ ڈار","C":"مولانا الطاف حسین","D":"مرزا واجد حسین"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation مولانا الطاف حسین', 0, 0, 0, 1790968560345) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tu_7f10a17cb81877f3', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_urdu_poets', 'کیا آپ سرسید احمد خان کے شروع کے اُستاد کانام بتا سکتے ہیں', '{"A":"حمید الدین","B":"شجاح الدین","C":"صلاح الدین","D":"نظام الدین"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation حمید الدین', 0, 0, 0, 1790968560345) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tu_3558151935751615', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_urdu_poets', 'کیا آپ بتا سکتے ہیں کہ مولا نا الطاف حسین حالی پانی پت (انڈیا ) میں کب پیدا ہوئے', '{"A":"ء1830","B":"ء1833","C":"ء1836","D":"ء1838"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation ء1ء18ء18ء18ء18ء18ء1838ء18383838383838838', 0, 0, 0, 1790968560345) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tu_dc1cbfdcdbab8094', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_urdu_poets', 'ابوالکلام آزاد اور علامہ اقبال علی گڑھ تحریک کے علاوہ کس تحریک سے متاثر ہوئے؟', '{"A":"حقیقت پسند تحریک","B":"بھگتی تحریک","C":"نئی شاعری کی تحریک","D":"رومانوی تحریک"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation آپ بالکل درست ہیں! ابوالکلام آزاد اور علامہ اقبال دونوں رومانوی تحریک سے متاثر ہوئے۔ رومانوی تحریک نے فن، ادب اور فلسفے میں جذبات، خیالات اور تخلیقی اظہار کو اہمیت دی۔ اقبال کی شاعری اور آزاد کے نظریات میں اس تحریک کے اثرات واضح نظر آتے ہیں، خاص طور پر ان کی انسانیت، عشق اور آزادی کے تصورات میں۔', 0, 0, 0, 1790968560362) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tu_e7d02fd4a4699389', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_urdu_poets', 'پطرس بخاری کا اصل نام کیا ہے', '{"A":"سید احمد شاہ","B":"سائیں محمد افضل","C":"محمد غم خا","D":"فتح محمد"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation پشاور میں یکم اکتوبر1898 کو پیدا ہوئے۔ 5دسمبر 1958 کو ان کا انتقال ہوا۔پطرس کے مضامین (1928)، دیہات میں بوائے اسکاؤٹ (ترجمہ،1934)، تعلیم خصوصاً اوائل طفلی میں (برٹرنڈرسل کی تصنیف کا ترجمہ، 1935)، نوع انسان کی کہانی (ترجمہ، 1939)، ڈرامہ اور ٹھیٹر پر بہت سے مضامین ہیں', 0, 0, 0, 1790968560362) ON CONFLICT(id) DO NOTHING;
