INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tu_4aaeb2ca27c594be', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_urdu_idioms', 'وہ نام جو ماں باپ، بیٹا، بیٹی یا کسی اور نسبت سے مشہور ہو جائے مثلاً ابو قاسم، ابوتراب، ام کلثوم وغیرہ، کیا کہلاتے ہیں؟', '{"A":"خطاب","B":"کنیت","C":"لقب","D":"ان میں سے کوئی نہیں"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation کنیت وہ نام ہوتا ہے جو کسی شخص کو ماں، باپ یا کسی نسبت سے دیا جاتا ہے جیسے "ابو قاسم"۔یہ نام احتراماً یا پہچان کے لیے استعمال کیا جاتا ہے، عربی روایات میں عام ہے۔Last verified on 26-07-2026', 0, 0, 0, 1790968560393) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tu_99b04959c90952d8', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_urdu_idioms', 'آفتاب بام ہونا محاورہ ہے۔ اس کا مطلب کیا ہے؟', '{"A":"مرنے کے قریب ہونا","B":"سورج کا طلوع ہونا","C":"سورج کا غروب ہونا","D":"ان میں سے کوئی نہیں"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation آفتاب بام ہونا محاورے کا مطلب سورج کا غروب ہونا ہے۔یہ دن کے اختتام یا شام ہونے کی طرف اشارہ کرتا ہے۔یہ محاورہ ادبی اور شعری زبان میں بھی استعمال ہوتا ہے۔Last verified on 26-07-2026', 0, 0, 0, 1790968560393) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tu_7de78517a44a94bc', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_urdu_idioms', 'ٹسوے بہانا محاورہ ہے۔ اس کا مفہوم کیا ہے؟', '{"A":"جھوٹ موٹ کا رونا","B":"پانی بہانا","C":"پھوٹ پھوٹ کر رونا","D":"ان میں سے کوئی نہیں"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation محاورہ ٹسوے بہانا کا مطلب ہے بنا وجہ یا بنا حقیقت کے رونا۔یہ اس وقت استعمال ہوتا ہے جب کوئی شخص دکھاوے کے لیے روتا ہے۔اس کا اصل مفہوم جھوٹ موٹ کا رونا دکھانا ہے۔Last verified on 23-06-2026', 0, 0, 0, 1790968560393) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tu_9dacef1639fe2774', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_urdu_idioms', 'محاورہ مکمل کیجیے: آج ــــــ کل دوسرا دن۔', '{"A":"مرے","B":"سوئے","C":"گرے","D":"اٹھے"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation آج مرے کل دوسرا دن۔معانی: زندگی ناقابلِ اعتبار اور عارضی ہے، انسان کی موت کے بعد لوگ اسے جلد بھول جاتے ہیں اور معمولات زندگی چلتے رہتے ہیں۔', 0, 0, 0, 1790968560393) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tu_8f34a8d921cb76a5', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_urdu_idioms', 'درست ضرب المثل ہے: نو نقد نہ تیرا ______؟', '{"A":"پیسہ","B":"شمار","C":"ادھار","D":"ان میں سے کوئی نہیں"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation درست ضرب المثل ہے: نو نقد نہ تیرا ادھار۔اس ضرب المثل کا مطلب ہے کہ نقد فائدہ ادھار وعدے سے بہتر ہوتا ہے۔Last verified on 29-01-2026', 0, 0, 0, 1790968560393) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tu_42ad013022c8ae75', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_urdu_idioms', 'ضرب المثل آپ کاج مہا کاج سے کیا مراد ہے؟', '{"A":"جو کام خود کیا جائے، وہی بہتر ہے","B":"اپنا کام اچھا لگتا ہے","C":"اپنے کام کی خود تعریف کرنا","D":"ان میں سے کوئی نہیں"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation "آپ کاج مہا کاج" کا مطلب ہے کہ جو کام خود کیا جائے وہی بہتر ہوتا ہے', 0, 0, 0, 1790968560393) ON CONFLICT(id) DO NOTHING;
