INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tu_315bf38738b4086c', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_urdu_idioms', 'دو جملوں میں ربط کے لیے استعمال ہونے والے حروف مثلاۤ (کہ) کو ـــــ کہتے ہیں؟', '{"A":"حروفِ ربط","B":"حروفِ روابط","C":"حروفِ ضروری","D":"حروفِ بیان"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation · حروفِ ربط: یہ حروف ایک لفظ(اسم) کا تعلق دوسرے لفظ(فاعل یا مفعول ) سے ظاہر کرتے ہیں۔ جیسے کا، کی، کو، نے۔سے· اسلم کو کھانا دے دو۔ وہ علی کی کتاب ہے۔ بابر نے علی کو سلام کیا۔ ان جملوں میں ”کو، کی اور نے“ حروف ربط ہیں۔· · حروف عطف وہ حروف ہوتے ہیں جو دو اسموں یا دو جملوں کو آپس میں ملانے کے لیے استعمال ہوتے ہیں۔ جیسے قلم اور دوات میز پر رکھ دو، حنا کھانا کھا کر اسکول گئی۔ ان جملوں میں ”اور“ اور ”کر“ حروف عطف ہیں۔', 0, 0, 0, 1790968560460) ON CONFLICT(id) DO NOTHING;
