INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tu_39c9797dcf218353', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_urdu_meanings', 'لفظ اردو کے لغوی معنی کیا ہیں؟', '{"A":"زبان","B":"ادب","C":"لشکر","D":"مقامی بولی"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation اردو ترکی زبان کا لفظ ہے جس کے بنیادی لغوی معنی لشکر، فوج، چھاؤنی، یا شاہی پڑاؤ کے ہیں۔ماخذ: یہ لفظ ترکی زبان کے لفظ ''اوردو'' سے نکلا ہے۔تسمیہ: مغل دور میں دہلی کے شاہی کیمپ یا فوجیوں کے بازار کو "اردوئے معلیٰ" (اعلیٰ لشکر گاہ) کہا جاتا تھا، اور وہاں بولی جانے والی زبان "زبانِ اردوئے معلیٰ" (لشکری زبان) کہلائی، جو وقت کے ساتھ صرف "اردو" رہ گئی۔Last updated question by NA on 11 May 2026', 0, 0, 0, 1790968560657) ON CONFLICT(id) DO NOTHING;
