INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tu_57062cdb4beca062', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_urdu_meanings', 'اساطير کا مطلب ھے؟', '{"A":"وساطير","B":"مزاحيہ قصے","C":"تاريخی قصے","D":"ساطر"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation اساطیر الاولین ایک عربی اصطلاح ہے جو قرآن میں بھی استعمال ہوا ہے۔ یہ دو الفاظ کا مرکب ہے یعنی اساطیراور اولین۔ اساطیر جو اُسطُورۃ کی جمع ہے، جس کے معنی قصہ یا داستان ہے۔ اولین اول کی جمع ہے ،جس کے معنی پہلے یا گزشتہ لوگ ہے۔ اس مرکب کے دونوں الفاظ کے معنی ہیں گزشتہ لوگوں کے قصے اور کہانیاں یا گزشتہ اقوام کی داستانیں ۔’’قدیم مذہبوں میں دیوی دیوتاؤں اور خداؤں کے قصے کہانیاں ‘‘ قرآن کریم کی نو سورتوں میں اساطیر الاولین(اگلے لوگوں کی دیوکتھاؤں) کا ذکر آتا ہے', 0, 0, 0, 1790968560735) ON CONFLICT(id) DO NOTHING;
