INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tu_e20aba6cabd684c8', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_urdu_general', 'اہل زبان کی مخصوص بول چال جس میں لفظ حقیقی معنوں میں استعمال ہو، وہ کیا کہلاتا ہے؟', '{"A":"روزمرہ","B":"محاورہ","C":"مصدر","D":"ان میں سے کوئی نہیں"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation روزمرہ سے مراد ہے اہلِ زبان کی عام اور مخصوص بول چال۔اس میں الفاظ اپنے حقیقی معنوں میں استعمال ہوتے ہیں، محاوروں کے برعکس۔Last verified on 02-10-2026', 0, 0, 0, 1790968560798) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tu_62fafccd7aaf4386', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_urdu_general', 'جب کسی لفظ کے آخر میں اضافی الفاظ شامل کیے جائیں تو وہ کیا کہلاتے ہیں؟', '{"A":"سابقہ","B":"لاحقہ","C":"مترادف","D":"مرکب"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation لاحقہ وہ حروف یا الفاظ ہیں جو کسی لفظ کے آخر میں شامل کیے جاتے ہیں۔سابقہ کسی لفظ کے شروع میں شامل ہوتا ہے۔مثال: علم + ی = علمی۔Last verified on 02-10-2026', 0, 0, 0, 1790968560798) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tu_56c1679965b8e636', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_urdu_general', 'اپنے منہ میاں مٹھو بننا کیا ہے؟', '{"A":"کہاوت","B":"محاورہ","C":"ضرب المثل","D":"اسم معرفہ"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation اپنے منہ میاں مٹھو بننا اردو زبان کا ایک مشہور محاورہ ہے۔اس کا مطلب ہے خود ہی اپنی تعریف کرنا۔جب کوئی شخص اپنی خوبیوں یا کامیابیوں کا بڑھ چڑھ کر ذکر کرے تو یہ محاورہ استعمال ہوتا ہے۔Last verified on 10-08-2026', 0, 0, 0, 1790968560798) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tu_bedf6ad6d0a943b7', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_urdu_general', 'غیر معین شخص کے لیے بولے جانے والے الفاظ کیا کہلاتے ہیں؟', '{"A":"اسم صغیر","B":"اسم ضمیر","C":"اسم تنکیر","D":"اسم اسفہام"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation اسمِ تنکیر ایسے اسم کو کہتے ہیں جو غیر معین شخص، چیز یا مقام کے لیے استعمال ہو۔مثال: ایک آدمی، کوئی شخص، ایک کتاب۔Last verified on 28-07-2026', 0, 0, 0, 1790968560798) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tu_32868356f1fa1594', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_urdu_general', 'ان میں سے غلط لفظ کی نشاندہی کریں ہیں: حیرانگی، زندگی، شگفتگی، شستگی', '{"A":"حیرانگی","B":"زندگی","C":"شگفتگی","D":"شستگی"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation حیرانگی غلط لفظ ہے، درست لفظ حیرانی ہے۔لفظ حیران کے ساتھ لاحقہ "گی" استعمال نہیں ہوتا، جبکہ زندگی، شگفتگی اور شستگی درست الفاظ ہیں۔Last verified on 28-07-2026', 0, 0, 0, 1790968560798) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tu_bde0377beed49106', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_urdu_general', 'ان میں کونسا لفظ درست ہے؟ اسلام و علیکم، ولسلام علیکم، السلام علیکم، ان میں سے کوئی نہیں', '{"A":"اسلام و علیکم","B":"ولسلام علیکم","C":"السلام علیکم","D":"ان میں سے کوئی نہیں"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation درست سلام "السلام علیکم" ہے، جس کا مطلب ہے آپ پر سلامتی ہو۔یہ مسلمانوں کے درمیان سلام کرنے کا مسنون طریقہ ہے۔', 0, 0, 0, 1790968560798) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tu_ea845eaab34702ee', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_urdu_general', 'کسی بھی کام کے کرنے، ہونے یا سہنے کو کیا کہتے ہیں؟', '{"A":"فعل","B":"فاعل","C":"مفعول","D":"ان میں سے کوئی نہیں"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation فعل کسی کام کے کرنے، ہونے یا سہنے کو کہا جاتا ہے۔یہ جملے میں عمل یا کارروائی کو ظاہر کرتا ہے، جیسے "چلنا"، "کھانا"، "سوچنا" وغیرہ۔Last verified on 23-06-2026', 0, 0, 0, 1790968560798) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tu_672fe5ab73cc1e51', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_urdu_general', 'ایک بڑے جملے میں بہت سے چھوٹے جملوں کو الگ کرنے کے لیے یہ علامت استعمال کی جاتی ہے؟', '{"A":"سکتہ","B":"وقفہ","C":"قوسین","D":"فراق"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation سکتہ (،) کو جملے میں چھوٹے حصوں یا فقرات کو الگ کرنے کے لیے استعمال کیا جاتا ہے۔یہ جملے کو واضح اور بامعنی بنانے میں مدد دیتا ہے۔باقی علامات مختلف مقاصد کے لیے استعمال ہوتی ہیں۔Last verified on 21-06-2026', 0, 0, 0, 1790968560798) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tu_e8d641078fcbfa48', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_urdu_general', 'فرہنگ آصفیہ کس نے مرتب کی؟', '{"A":"سید احمد دہلوی","B":"ڈپٹی نذیر احمد","C":"رام بابو سکسینہ","D":"ان میں سے کوئی نہیں"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation فرہنگ آصفیہ کو سید احمد دہلوی نے مرتب کیا تھا۔یہ اردو زبان کی ایک مشہور اور مستند لغت ہے۔اس میں اردو الفاظ کے معنی، استعمال اور تشریحات شامل ہیں۔Last verified on 02-06-2026', 0, 0, 0, 1790968560824) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tu_7a65d02321dcc200', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_urdu_general', 'بانگ درا کا اولین دیباچہ کس نے لکھا؟', '{"A":"مولانا حالی","B":"سر راس مسعود","C":"جاوید اقبال","D":"شیخ عبدالقادر"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation بانگِ درا کے دیباچے کے مصنف سر عبد القادر ہیں۔سر عبد القادر علامہ اقبال کے قریبی دوستوں میں شامل تھے اور انہوں نے اس مجموعے پر مفصل مقدمہ لکھا۔بانگِ درا علامہ اقبال کا پہلا اردو شعری مجموعہ ہے جو 1924ء میں شائع ہوا اور تقریباً 20 سال کے کلام پر مشتمل ہے۔Last verified on 02-06-2026', 0, 0, 0, 1790968560824) ON CONFLICT(id) DO NOTHING;
