INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tu_e9a9fbdc3210d853', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_urdu_general', 'How many alphabets are there in Urdu?', '{"A":"39","B":"30","C":"40","D":"36"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation Urdu alphabet commonly has 39 basic letters.Some books mention 36 letters, but 39 is more accurate.With additional signs, total becomes 52 characters.Urdu is written right to left.It is influenced by Arabic, Persian, and some Sanskrit sounds.Last verified on 31-03-2026', 0, 0, 0, 1790968560824) ON CONFLICT(id) DO NOTHING;
