INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tu_f4c971262429e6f7', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_urdu_general', 'کسی ايک چيز کو کسی خوبی يا خامی کی وجہ سے کسی دوسری چيز کي مانند قرار دینا کیا کہلاتا ہے؟', '{"A":"فاعل","B":"اسم صفت","C":"مسند","D":"تشبیہ"}', 'D', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation جب کسی ایک چیز کو کسی خوبی یا خامی کی بنا پر دوسری چیز کے مشابہ قرار دیا جائے، تو اسے تشبیہ کہتے ہیں۔مثال: "علی شیر کی طرح بہادر ہے" — یہاں علی کو شیر سے تشبیہ دی گئی ہے۔', 0, 0, 0, 1790968560868) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tu_e5431ced7162de27', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_urdu_general', 'میں، سے، پر، تک، کا، نے  وغیرہ حروف کونسے ہیں؟', '{"A":"ضمیرات","B":"فعل","C":"حروف جار","D":"صفت"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation میں، سے، پر، تک، کا، نے جیسے الفاظ حروف جار کہلاتے ہیں کیونکہ یہ الفاظ جملے میں اسم کے ساتھ مخصوص تعلق ظاہر کرتے ہیں۔یہ جگہ، وقت یا تعلق کا پتہ دیتے ہیں، جیسے "کتاب میں رکھا ہے"۔', 0, 0, 0, 1790968560868) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tu_886c94687fdd8fc0', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_urdu_general', 'جب دو الفاظ آپس میں حمزہ اور "زَبر" یا "کا، کے، کی" ذریعے ملے ہوں تو اسے کیا کہتے ہیں؟', '{"A":"مرکب اضافی","B":"مرکب اشاری","C":"مرکب تام","D":"ان میں سے کوئی نہیں"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation مرکب اضافی وہ ہوتا ہے جس میں دو اسم ایسے ملیں کہ پہلے اسم کی دوسرے اسم سے نسبت ہو، جیسے "علم کا دروازہ"، "بچوں کی کتاب"۔اس میں "کا، کے، کی" یا زبر (اضافت) استعمال ہوتی ہے۔', 0, 0, 0, 1790968560868) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tu_07afa5ab4b9416c6', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_urdu_general', 'ایسے حروف جو جوش، خوشی اور غم میں بے اختیار بے زبان سے نکلیں، وہ کیا کہلاتے ہیں؟', '{"A":"حروف فجائیہ","B":"حروف بیان","C":"حروف علت","D":"ان میں سے کوئی نہیں"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation حروف فجائیہ وہ حروف یا آوازیں ہوتی ہیں جو جوش، غم یا خوشی کے احساسات کے اظہار کے طور پر بے اختیار نکلتی ہیں۔مثالیں: "آہ"، "اوہ"، "ہائے"، وغیرہ۔', 0, 0, 0, 1790968560893) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tu_c3791f8e2fabb047', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_urdu_general', 'وہ کیا ہے جو کسی جاندار، بے جان چیز، جگہ، مقام یا شخص کے نام کو ظاہر کرے؟', '{"A":"حرف","B":"فعل","C":"اسم","D":"اسم نکرہ"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation اسم ایسے لفظ کو کہتے ہیں جو کسی جاندار، بے جان چیز، جگہ یا شخص کا نام ظاہر کرے۔اردو گرامر میں اسم کو "نام" کے طور پر پہچانا جاتا ہے، جیسے: علی، کتاب، لاہور۔', 0, 0, 0, 1790968560893) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tu_57beed107ab25184', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_urdu_general', 'ایک کہانی بڑی پرانی کو سی صنف ہے؟', '{"A":"داستان","B":"افسانہ","C":"ناول","D":"ان میں سے کوئی نہیں"}', 'A', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation ایک کہانی بڑی پرانی کی صنف داستان ہے، جو عموماً روایتی اور قدیم قصوں کو ظاہر کرتی ہے۔داستان میں عام طور پر ماضی کی اہم یا تخیلاتی کہانیاں شامل ہوتی ہیں، جو زبانی طور پر منتقل کی جاتی ہیں۔', 0, 0, 0, 1790968560893) ON CONFLICT(id) DO NOTHING;
INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tu_2167326846c4287b', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_urdu_general', 'وہ خاص نام جو کسی خوبی یا وصف کی وجہ سے مشہور ہو جائے اسے کیا کہتے ہیں؟', '{"A":"خطاب","B":"کنیت","C":"لقب","D":"عرف"}', 'C', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation وہ خاص نام جو کسی خاص خوبی کی وجہ سے مشہور ہو جائے اسے لقب کہتے ہیں۔لقب کی مثالیں :خلیل اللہ، حضرت ابراہیم علیہ السلام کا لقب ہے آپ اللہ کے دوست تھے۔کلیم اللہ، حضرت موسیٰ علیہ السلام کا لقب ہے آپ اللہ سے کوہ طور پر ہمکلام ہوئے****عرف* وہ نام جو اصلی نام کی جگہ محبت یا حقارت کی وجہ سے مشہور ہو جائے عرف کہلاتا ہے۔ND-21-5-2023', 0, 0, 0, 1790968560893) ON CONFLICT(id) DO NOTHING;
