INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tu_0f3d45b1a63f2fd3', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_urdu_general', 'نشاں یہی ہےزمانے میں زندہ قوموں کا کہ صبح شام بدلتی ہیں اْن کی۔۔۔۔۔۔۔۔۔۔۔۔۔۔۔۔۔۔۔۔۔۔۔۔۔۔۔۔', '{"A":"تدبیریں","B":"تقدیریں","C":"شمشیریں","D":"تفسیریں"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation نشاں یہی ہے زمانے میں زندہ قوموں کاکہ صُبح و شام بدلتی ہیں ان کی تقدیریںارمغان حجاز ۔۔۔۔۔۔۔نظم نمبر 13*#تشریح* شعر کا مطلب یہ ہے کہ اگر تم یہ معلوم کرنا چاہتے ہو کہ فُلاں قوم زندہ ہے یا مُردہ تو اُس کی پہچان یہ ہے کہ اگر اُس قوم کی حالت میں ہر روز تبدیلی ہوتی رہتی ہے (اس کی تقدیریں صبح و شام بدلتی رہتی ہیں) تو سمجھ لو کہ وہ زندہ ہے اور اگر تم دیکھو کہ اُس قوم کی زندگی میں کوٸی تغیّر نہیں ہوتا تو سمجھ لو کہ وہ قوم مُردہ ہے۔', 0, 0, 0, 1790968561429) ON CONFLICT(id) DO NOTHING;
