INSERT INTO mcq (id, user_id, subject_id, question, options, correct, explanation, solve_later, attempt_count, wrong_count, created_at) VALUES ('mcq_tu_f3da9ff84255caf7', 'MwTB4GiNpIU33f2LJwseFripYqrDHSc0', 'top_urdu_general', 'وہ حروف جن پر "ال" عربی آتا ہے مگر پڑھا نہیں جاتا ان حروف کو ــــــ کہتے ہیں۔', '{"A":"حروفِ قمری","B":"حروفِ شمسی","C":"ان میں سے کوئی بھی نہیں","D":"حروفِ ابجد"}', 'B', '(0) اس سوال کو وضاحت کے ساتھ پڑھیں Explanation وہ حروف جن پر "ال" عربی آتا ہے مگر پڑھا نہیں جاتا ان حروف کو حروفِ شمسی کہتے ہیںان حروف سے پہلے جب "ال" آتا ہے تو لام (ل) کی آواز نہیں نکالی جاتی، جیسے: الشمس (اَشّمس)، الرحیم (اَرّحیم).ان کے مقابلے میں جن حروف کے ساتھ "ال" پڑھا جائے، انہیں حروفِ قمری کہتے ہیں (جیسے: القمر)Last updated question by NA on 07 May 2026', 0, 0, 0, 1790968561445) ON CONFLICT(id) DO NOTHING;
